contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value, uint value2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value, "not enough balance for deposit");
        uint preBalance = address(this).balance;
        c.deposit{value: value}(); if (__ESBMC_reverted()) return;
        uint postDepositBalance = address(this).balance;
        uint preC = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint postBalance = address(this).balance;
        uint postC = address(c).balance;

        bool zeroDeposit = (value == 0);
        assert(
            !reverted &&
            (zeroDeposit ? (preBalance == postBalance && preC == postC)
                         : (postBalance == preBalance && postC == preC - value))
        );
    }

    receive() external payable {}
