import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 value, uint256 value2) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint preBalance = address(this).balance;
        try c.deposit{value: value}() {} catch { return; }
        uint postDepositBalance = address(this).balance;
        uint preC = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint postBalance = address(this).balance;
        uint postC = address(c).balance;
        bool zeroDeposit = (value == 0);
        assertTrue(!reverted &&
            (zeroDeposit ? (preBalance == postBalance && preC == postC)
                         : (postBalance == preBalance && postC == preC - value)));
    }

    function testFuzz_run(uint256 value, uint256 value2) public {
        _run(value, value2);
    }

    receive() external payable {}
}
